<?php require dirname(__DIR__).'/bootstrap.php';require_admin();$page=(string)($_GET['page']??'dashboard');$allowed=['dashboard','bookings','drivers','vehicles','settings','prices','requests','invoices','backups'];if(!in_array($page,$allowed,true))$page='dashboard';$message='';$error='';
try{$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='settings'){foreach(['google_maps_browser_key','google_routes_server_key','google_geocoding_server_key','google_routes_enabled','distance_rate','airport_extra','station_extra','traffic_eur_per_30min','morning_surcharge','evening_surcharge'] as $key){if(!array_key_exists($key,$_POST))continue;$value=trim((string)$_POST[$key]);if(str_ends_with($key,'_key') && $value==='')continue;if(strlen($value)>2000)throw new RuntimeException('Valeur trop longue');$s=$pdo->prepare('INSERT INTO islem_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute([$key,$value]);}$message='Réglages enregistrés.';}
elseif($action==='booking_status'){$s=$pdo->prepare('UPDATE islem_bookings SET status=? WHERE id=?');$st=(string)($_POST['status']??'');if(!in_array($st,['pending','confirmed','assigned','in_progress','completed','cancelled'],true))throw new RuntimeException('Statut incorrect');$s->execute([$st,(int)($_POST['id']??0)]);$message='Réservation mise à jour.';}
elseif($action==='driver'){$s=$pdo->prepare('INSERT INTO islem_drivers(first_name,last_name,email,phone,verified,active) VALUES(?,?,?,?,0,1)');$s->execute([clean((string)$_POST['first_name'],120),clean((string)$_POST['last_name'],120),trim((string)($_POST['email']??'')),trim((string)($_POST['phone']??''))]);$message='Chauffeur ajouté. Vérifiez ses documents avant de lui attribuer un badge.';}
elseif($action==='vehicle'){$s=$pdo->prepare('INSERT INTO islem_vehicles(driver_id,make,model,registration,active,compliant) VALUES(?,?,?,?,1,0)');$s->execute([(int)$_POST['driver_id'],clean((string)$_POST['make'],100),clean((string)$_POST['model'],120),clean((string)$_POST['registration'],30)]);$message='Véhicule ajouté, conformité à vérifier.';}
elseif($action==='driver_validation'){
 $id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Chauffeur incorrect');
 $items=['vtc_card','passenger_insurance','transport_registration'];
 $pdo->beginTransaction();
 try{
  foreach($items as $type){
   $validated=isset($_POST[$type])?1:0;
   $s=$pdo->prepare('SELECT id FROM islem_driver_documents WHERE driver_id=? AND document_type=? LIMIT 1');$s->execute([$id,$type]);$doc=$s->fetchColumn();
   if($doc){$s=$pdo->prepare('UPDATE islem_driver_documents SET validated=? WHERE id=?');$s->execute([$validated,$doc]);}
   else {$s=$pdo->prepare('INSERT INTO islem_driver_documents(driver_id,document_type,validated) VALUES(?,?,?)');$s->execute([$id,$type,$validated]);}
  }
  $verified=count($_POST)>0 && count(array_filter($items,fn($t)=>isset($_POST[$t])))===count($items)?1:0;
  $s=$pdo->prepare('UPDATE islem_drivers SET verified=? WHERE id=?');$s->execute([$verified,$id]);
  $pdo->commit();$message='Justificatifs du chauffeur mis à jour.';
 }catch(Throwable $ex){$pdo->rollBack();throw $ex;}
}
elseif($action==='vehicle_validation'){
 $id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Véhicule incorrect');
 $compliant=isset($_POST['compliant'])?1:0;
 $s=$pdo->prepare('UPDATE islem_vehicles SET compliant=? WHERE id=?');$s->execute([$compliant,$id]);$message='Conformité du véhicule mise à jour.';
}
elseif($action==='review_change'){$svc=new \Islem\Extension\CustomerBooking($pdo);$svc->review((int)($_POST['request_id']??0),(int)$_SESSION['admin_id'],($_POST['decision']??'')==='approve');$message='Demande traitée.';}
else throw new RuntimeException('Action inconnue');}
}catch(Throwable $e){$error=$e->getMessage();}
function all_rows(string $sql):array{try{return db()->query($sql)->fetchAll();}catch(Throwable $e){return [];}}
function cfg(string $k,string $default=''):string{try{return setting($k,$default);}catch(Throwable $e){return $default;}}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administration · ISLEM VTC</title><link rel="stylesheet" href="/assets/style.css"></head><body><div class="admin"><aside class="sidebar"><div class="brand">ISLEM VTC</div><p>Administration</p><?php foreach(['dashboard'=>'Tableau de bord','bookings'=>'Réservations','drivers'=>'Chauffeurs','vehicles'=>'Véhicules','prices'=>'Tarifs','settings'=>'Google Maps et API','requests'=>'Demandes de modification','invoices'=>'Factures','backups'=>'Sauvegardes'] as $slug=>$label): ?><a href="?page=<?=e($slug)?>"><?=e($label)?></a><?php endforeach; ?><a href="/">Voir le site</a><a href="/is/logout.php">Déconnexion</a></aside><main class="admin-main"><h1><?=e(ucfirst($page))?></h1><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><?php if($message): ?><p class="success"><?=e($message)?></p><?php endif; ?>
<?php if($page==='dashboard'): ?><?php $book=all_rows('SELECT COUNT(*) n FROM islem_bookings');$drivers=all_rows('SELECT COUNT(*) n FROM islem_drivers');$cars=all_rows('SELECT COUNT(*) n FROM islem_vehicles'); ?><div class="admin-grid"><div class="stat">Réservations<br><strong><?= (int)($book[0]['n']??0) ?></strong></div><div class="stat">Chauffeurs<br><strong><?= (int)($drivers[0]['n']??0) ?></strong></div><div class="stat">Véhicules<br><strong><?= (int)($cars[0]['n']??0) ?></strong></div></div><div class="panel" style="margin-top:22px"><h2>ISLEM VTC</h2><p>Utilisez le menu pour configurer Google Maps, consulter les réservations et gérer vos chauffeurs.</p></div>
<?php elseif($page==='bookings'): ?><div class="panel tablewrap"><table><tr><th>Référence</th><th>Trajet</th><th>Date UTC</th><th>Prix</th><th>État</th></tr><?php foreach(all_rows('SELECT id,booking_code,pickup_address,dropoff_address,pickup_at,quoted_total,status FROM islem_bookings ORDER BY id DESC LIMIT 150') as $r): ?><tr><td><?=e($r['booking_code'])?></td><td><?=e($r['pickup_address'])?> → <?=e($r['dropoff_address'])?></td><td><?=e($r['pickup_at'])?></td><td><?=e((string)$r['quoted_total'])?> €</td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="booking_status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><?php foreach(['pending','confirmed','assigned','in_progress','completed','cancelled'] as $st): ?><option <?= $r['status']===$st?'selected':'' ?> value="<?=$st?>"><?=$st?></option><?php endforeach; ?></select><button class="btn" style="padding:7px">OK</button></form></td></tr><?php endforeach; ?></table></div>
<?php elseif($page==='settings'||$page==='prices'): ?><div class="panel" style="max-width:750px"><h2><?= $page==='settings'?'Google Maps et Google Routes':'Tarification ISLEM VTC' ?></h2><p class="muted">Enregistré dans MySQL. Les clés Google doivent être limitées aux domaines/IP appropriés depuis Google Cloud.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="settings"><?php $fields=$page==='settings'?['google_maps_browser_key'=>'Clé Google Maps / Places navigateur','google_routes_server_key'=>'Clé Google Routes serveur','google_geocoding_server_key'=>'Clé Google Geocoding serveur','google_routes_enabled'=>'Google Routes activé (1 / 0)']:['distance_rate'=>'Tarif par kilomètre (€)','airport_extra'=>'Supplément aéroport (€)','station_extra'=>'Supplément gare (€)','traffic_eur_per_30min'=>'Trafic : € par 30 min','morning_surcharge'=>'Majoration matin (€)','evening_surcharge'=>'Majoration soir (€)'];foreach($fields as $k=>$label): ?><div class="field"><label><?=e($label)?></label><input name="<?=e($k)?>" value="<?=e(cfg($k))?>" <?=str_contains($k,'_key')?'type="password" autocomplete="new-password"':'type="text"'?>></div><?php endforeach; ?><button class="btn">Enregistrer</button></form></div>
<?php elseif($page==='drivers'): ?><div class="panel"><h2>Ajouter un chauffeur</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="driver"><?php foreach(['first_name'=>'Prénom','last_name'=>'Nom','email'=>'E-mail','phone'=>'Téléphone'] as $k=>$v): ?><div class="field"><label><?=e($v)?></label><input name="<?=e($k)?>" <?=in_array($k,['first_name','last_name'])?'required':''?>></div><?php endforeach; ?><button class="btn">Ajouter</button></form><h2>Vérification des chauffeurs</h2><p class="muted">Cochez uniquement les documents dont vous avez personnellement vérifié l’authenticité et la validité. Le badge global est accordé seulement si les trois contrôles sont validés.</p>
<?php foreach(all_rows('SELECT id,first_name,last_name,verified FROM islem_drivers ORDER BY id DESC') as $d): ?><?php $docs=all_rows('SELECT document_type,validated FROM islem_driver_documents WHERE driver_id='.(int)$d['id']);$checks=[];foreach($docs as $doc){$checks[$doc['document_type']]=(bool)$doc['validated'];} ?><div class="card"><strong><?=e($d['first_name'].' '.$d['last_name'])?></strong> · <?= $d['verified']?'✅ Chauffeur vérifié':'⏳ Vérification incomplète' ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="driver_validation"><input type="hidden" name="id" value="<?=(int)$d['id']?>"><div class="verification-options"><label><input type="checkbox" name="vtc_card" value="1" <?=!empty($checks['vtc_card'])?'checked':''?>> Carte professionnelle VTC contrôlée</label><label><input type="checkbox" name="passenger_insurance" value="1" <?=!empty($checks['passenger_insurance'])?'checked':''?>> Assurance véhicule et passagers contrôlée</label><label><input type="checkbox" name="transport_registration" value="1" <?=!empty($checks['transport_registration'])?'checked':''?>> Inscription au registre VTC contrôlée</label></div><button class="btn" type="submit">Enregistrer les vérifications</button></form></div><?php endforeach; ?></div>
<?php elseif($page==='vehicles'): ?><div class="panel"><h2>Ajouter un véhicule</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="vehicle"><div class="field"><label>Chauffeur</label><select name="driver_id" required><?php foreach(all_rows('SELECT id,first_name,last_name FROM islem_drivers') as $d): ?><option value="<?=(int)$d['id']?>"><?=e($d['first_name'].' '.$d['last_name'])?></option><?php endforeach; ?></select></div><?php foreach(['make'=>'Marque','model'=>'Modèle','registration'=>'Immatriculation'] as $k=>$label): ?><div class="field"><label><?=e($label)?></label><input required name="<?=e($k)?>"></div><?php endforeach; ?><button class="btn">Ajouter</button></form><h2>Conformité des véhicules</h2><p class="muted">Activez « conforme » uniquement après vérification des pièces et obligations applicables au véhicule.</p><?php foreach(all_rows('SELECT id,make,model,registration,compliant FROM islem_vehicles ORDER BY id DESC') as $v): ?><div class="card"><strong><?=e($v['make'].' '.$v['model'].' · '.$v['registration'])?></strong> · <?= $v['compliant']?'✅ Véhicule conforme':'⏳ À vérifier' ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="vehicle_validation"><input type="hidden" name="id" value="<?=(int)$v['id']?>"><div class="verification-options"><label><input type="checkbox" name="compliant" value="1" <?=$v['compliant']?'checked':''?>> Véhicule conforme après contrôle</label></div><button class="btn">Enregistrer la conformité</button></form></div><?php endforeach; ?></div>
<?php elseif($page==='requests'): ?><div class="panel"><h2>Demandes de modifications</h2><?php foreach(all_rows('SELECT id,booking_id,customer_message,state FROM islem_booking_change_requests ORDER BY id DESC LIMIT 100') as $r): ?><div class="card"><strong>Réservation #<?=(int)$r['booking_id']?></strong> · <?=e($r['state'])?><p><?=e($r['customer_message'])?></p><?php if($r['state']==='pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="review_change"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="btn" name="decision" value="approve">Approuver</button> <button class="btn outline" name="decision" value="reject">Rejeter</button></form><?php endif; ?></div><?php endforeach; ?></div>
<?php elseif($page==='invoices'): ?><div class="panel"><h2>Factures</h2><p>Module PDF présent dans <code>/module/Invoice.php</code>. La génération et l'expédition SMTP/API doivent être reliées à un flux de paiement validé avant activation publique.</p></div>
<?php elseif($page==='backups'): ?><div class="panel"><h2>Sauvegardes</h2><p>Module disponible dans <code>/module/Backup.php</code>. Configurer une tâche planifiée chez l'hébergeur si autorisée ; stocker les sauvegardes hors du dossier public.</p></div><?php endif; ?></main></div></body></html>